var BRANCH_REL_TEXT = {
  \uD569: "\uC624\uB298\uC758 \uC9C0\uC9C0\uAC00 \uB2F9\uC2E0\uC758 \uC77C\uC9C0\uC640 \uD569\uC744 \uC774\uB8F9\uB2C8\uB2E4. \uC0AC\uB78C\uACFC\uC758 \uC0AC\uC774\uAC00 \uBD80\uB4DC\uB7FD\uAC8C \uD480\uB9AC\uB294 \uB0A0\uC774\uB77C, \uBD80\uD0C1\uD558\uAC70\uB098 \uD654\uD574\uD558\uAE30\uC5D0 \uC88B\uC740 \uD0C0\uC774\uBC0D\uC785\uB2C8\uB2E4.",
  \uCDA9: "\uC624\uB298\uC758 \uC9C0\uC9C0\uAC00 \uB2F9\uC2E0\uC758 \uC77C\uC9C0\uC640 \uCDA9\uC744 \uC774\uB8F9\uB2C8\uB2E4. \uC6C0\uC9C1\uC784\uACFC \uBCC0\uD654\uAC00 \uC0DD\uAE30\uAE30 \uC26C\uC6B4 \uB0A0\uC774\uB2C8, \uC774\uB3D9\uACFC \uC77C\uC815\uC5D0 \uC5EC\uC720\uB97C \uB450\uC138\uC694.",
  \uD615: "\uC624\uB298\uC758 \uC9C0\uC9C0\uAC00 \uB2F9\uC2E0\uC758 \uC77C\uC9C0\uC640 \uD615\uC744 \uC774\uB8F9\uB2C8\uB2E4. \uB9D0\uC774 \uB0A0\uCE74\uB85C\uC6CC\uC9C0\uAE30 \uC26C\uC6B4 \uB0A0\uC774\uB77C, \uBCF4\uB0B4\uAE30 \uC804\uC5D0 \uD55C \uBC88 \uB354 \uB2E4\uB4EC\uC73C\uBA74 \uBB34\uB9AC \uC5C6\uC774 \uC9C0\uB098\uAC11\uB2C8\uB2E4.",
  \uC6D0\uC9C4: "\uC624\uB298\uC758 \uC9C0\uC9C0\uAC00 \uB2F9\uC2E0\uC758 \uC77C\uC9C0\uC640 \uC6D0\uC9C4\uC744 \uC774\uB8F9\uB2C8\uB2E4. \uC774\uC720 \uC5C6\uC774 \uAC70\uC2AC\uB9AC\uB294 \uC0AC\uB78C\uC774\uB098 \uC0C1\uD669\uC774 \uC0DD\uAE38 \uC218 \uC788\uC73C\uB2C8, \uC624\uB298\uC740 \uD310\uB2E8\uC744 \uBBF8\uB904\uB450\uC138\uC694.",
  \uBB34\uAD00: "\uC624\uB298\uC758 \uC9C0\uC9C0\uB294 \uB2F9\uC2E0\uC758 \uC77C\uC9C0\uC640 \uD2B9\uBCC4\uD788 \uBD80\uB52A\uD788\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uD750\uB984\uC744 \uD06C\uAC8C \uBC29\uD574\uD558\uB294 \uAC83 \uC5C6\uC774 \uC9C0\uB098\uAC00\uB294 \uB0A0\uC785\uB2C8\uB2E4."
};
