var pairKey2 = (a, b2) => [a, b2].sort().join("");
var YUKHAP = ["\uC790\uCD95", "\uC778\uD574", "\uBB18\uC220", "\uC9C4\uC720", "\uC0AC\uC2E0", "\uC624\uBBF8"];
var CHUNG = ["\uC790\uC624", "\uCD95\uBBF8", "\uC778\uC2E0", "\uBB18\uC720", "\uC9C4\uC220", "\uC0AC\uD574"];
var WONJIN = ["\uC790\uBBF8", "\uCD95\uC624", "\uC778\uC720", "\uBB18\uC2E0", "\uC9C4\uD574", "\uC0AC\uC220"];
var HYEONG_PAIRS = ["\uC778\uC0AC", "\uC0AC\uC2E0", "\uC778\uC2E0", "\uCD95\uC220", "\uC220\uBBF8", "\uCD95\uBBF8", "\uC790\uBB18"];
var JAHYEONG = ["\uC9C4", "\uC624", "\uC720", "\uD574"];
var YUKHAP_SET = new Set(YUKHAP.map((s) => pairKey2(s[0], s[1])));
var CHUNG_SET = new Set(CHUNG.map((s) => pairKey2(s[0], s[1])));
var WONJIN_SET = new Set(WONJIN.map((s) => pairKey2(s[0], s[1])));
var HYEONG_SET = new Set(HYEONG_PAIRS.map((s) => pairKey2(s[0], s[1])));
function \uC9C0\uC9C0\uAD00\uACC4(a, b2) {
  if (a === b2) return JAHYEONG.includes(a) ? "\uD615" : "\uBB34\uAD00";
  const key = pairKey2(a, b2);
  if (CHUNG_SET.has(key)) return "\uCDA9";
  if (HYEONG_SET.has(key)) return "\uD615";
  if (YUKHAP_SET.has(key)) return "\uD569";
  if (WONJIN_SET.has(key)) return "\uC6D0\uC9C4";
  return "\uBB34\uAD00";
}
var TG_WEIGHT = {
  \uC2DD\uC2E0: 10,
  \uC815\uC7AC: 9,
  \uC815\uC778: 9,
  \uC815\uAD00: 8,
  \uD3B8\uC7AC: 5,
  \uBE44\uACAC: 4,
  \uD3B8\uC778: 3,
  \uC0C1\uAD00: 1,
  \uAC81\uC7AC: -1,
  \uD3B8\uAD00: -3
};
var UNSEONG_WEIGHT = {
  \uC7A5\uC0DD: 5,
  \uBAA9\uC695: 0,
  \uAD00\uB300: 4,
  \uAC74\uB85D: 5,
  \uC81C\uC655: 4,
  \uC1E0: -1,
  \uBCD1: -3,
  \uC0AC: -4,
  \uBB18: -3,
  \uC808: -4,
  \uD0DC: 0,
  \uC591: 2
};
var REL_WEIGHT = { \uD569: 7, \uBB34\uAD00: 0, \uC6D0\uC9C4: -5, \uCDA9: -7, \uD615: -8 };
var WEEKDAY = ["\uC77C", "\uC6D4", "\uD654", "\uC218", "\uBAA9", "\uAE08", "\uD1A0"];
function pad2(n) {
  return String(n).padStart(2, "0");
}
function ymd(d) {
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}
function \uC624\uB298\uC758\uC6B4\uC138(opts) {
  const { \uC77C\uAC04, \uC77C\uC9C0, \uC6A9\uC2E0, \uD76C\uC2E0, \uAE30\uC2E0, \uAD6C\uC2E0, date } = opts;
  const y = date.getFullYear(), mo = date.getMonth() + 1, d = date.getDate();
  const ij = \uC77C\uC9C4(y, mo, d);
  const gz = ij.\uAC04\uC9C0;
  const stemKo = gz[0], branchKo = gz[1];
  const dayStemHanja = STEM_K2H[\uC77C\uAC04];
  const stemTenGod = tenGod(dayStemHanja, STEM_K2H[stemKo]) || "\uBE44\uACAC";
  const branchTenGod = tenGod(dayStemHanja, BRANCH_MAIN[BRANCH_K2H[branchKo]]) || "\uBE44\uACAC";
  const unseong = \uC2ED\uC774\uC6B4\uC131\uB9F5(\uC77C\uAC04)[branchKo] || "";
  const rel = \uC9C0\uC9C0\uAD00\uACC4(branchKo, \uC77C\uC9C0);
  let score = 62;
  score += TG_WEIGHT[stemTenGod] ?? 0;
  score += Math.round((TG_WEIGHT[branchTenGod] ?? 0) * 0.6);
  score += UNSEONG_WEIGHT[unseong] ?? 0;
  score += REL_WEIGHT[rel];
  const todayElems = [STEM_ELEM_KO[stemKo], BRANCH_ELEM_KO[branchKo]];
  for (const el of todayElems) {
    if (el === \uC6A9\uC2E0) score += 6;
    else if (el === \uD76C\uC2E0) score += 3;
    else if (el === \uAE30\uC2E0) score -= 4;
    else if (el === \uAD6C\uC2E0) score -= 2;
  }
  score = Math.max(42, Math.min(96, score));
  const tone = score >= 76 ? "\uC21C\uD48D" : score >= 58 ? "\uBCF4\uD1B5" : "\uC8FC\uC758";
  const entry = TODAY_TEN_GOD[stemTenGod]?.[tone] ?? TODAY_TEN_GOD["\uBE44\uACAC"][tone];
  const band = SCORE_BAND.find((b2) => score >= b2.min);
  return {
    date: ymd(date),
    dateLabel: `${y}\uB144 ${mo}\uC6D4 ${d}\uC77C (${WEEKDAY[date.getDay()]})`,
    ganzhi: gz,
    ganzhiHanja: (STEM_K2H[stemKo] || "") + (BRANCH_K2H[branchKo] || ""),
    stemTenGod,
    branchTenGod,
    unseong,
    rel,
    relText: BRANCH_REL_TEXT[rel],
    score,
    band: band.label,
    bandLine: band.line,
    tone,
    keyword: entry.keyword,
    text: entry.text,
    lucky: LUCKY[\uC6A9\uC2E0] ?? LUCKY["\uD1A0"]
  };
}
function \uC6D4\uAC04\uC77C\uC9C4(year, month) {
  const last = new Date(year, month, 0).getDate();
  const out = [];
  for (let d = 1; d <= last; d++) {
    const gz = \uC77C\uC9C4(year, month, d).\uAC04\uC9C0;
    out.push({
      day: d,
      ganzhi: gz,
      hanja: (STEM_K2H[gz[0]] || "") + (BRANCH_K2H[gz[1]] || ""),
      weekday: new Date(year, month - 1, d).getDay()
    });
  }
  return out;
}

