var DAY_STEM = {
  \uAC11: {
    image: "\uACE7\uAC8C \uC790\uB77C\uB294 \uD070 \uB098\uBB34",
    text: "\uC704\uB85C \uC790\uB77C\uB294 \uC131\uC9C8\uC774\uB77C \uBAA9\uD45C\uAC00 \uBD84\uBA85\uD560 \uB54C \uAC00\uC7A5 \uAC15\uD569\uB2C8\uB2E4. \uB0A8 \uBC11\uC5D0\uC11C \uC624\uB798 \uB20C\uB824 \uC788\uB294 \uAC78 \uACAC\uB514\uAE30 \uC5B4\uB824\uC6CC\uD558\uACE0, \uC790\uAE30 \uC774\uB984\uC73C\uB85C \uD558\uB294 \uC77C\uC5D0\uC11C \uC2E4\uB825\uC774 \uC81C\uB300\uB85C \uB098\uC635\uB2C8\uB2E4. \uB2E4\uB9CC \uD55C\uBC88 \uC815\uD55C \uBC29\uD5A5\uC744 \uBC14\uAFB8\uB294 \uB370 \uC2DC\uAC04\uC774 \uC624\uB798 \uAC78\uB824\uC11C, \uC544\uB2C8\uB77C\uB294 \uC2E0\uD638\uB97C \uC77C\uCC0D \uBC1B\uC544\uB4E4\uC774\uB294 \uC5F0\uC2B5\uC774 \uD544\uC694\uD569\uB2C8\uB2E4."
  },
  \uC744: {
    image: "\uBC14\uB78C\uC5D0 \uD718\uB294 \uD480\uACFC \uB369\uAD74",
    text: "\uBD80\uB7EC\uC9C0\uC9C0 \uC54A\uACE0 \uD718\uC5B4\uC11C \uBC84\uD2F0\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uC0C1\uD669\uC5D0 \uB9DE\uCDB0 \uC790\uAE30\uB97C \uC870\uC815\uD558\uB294 \uB2A5\uB825\uC774 \uB6F0\uC5B4\uB098 \uC5B4\uB514\uC5D0 \uB193\uC544\uB3C4 \uC0B4\uC544\uB0A8\uACE0, \uC0AC\uB78C \uC0AC\uC774\uC758 \uC628\uB3C4 \uBCC0\uD654\uB97C \uB0A8\uBCF4\uB2E4 \uBA3C\uC800 \uC54C\uC544\uCC55\uB2C8\uB2E4. \uB300\uC2E0 \uB9DE\uCD94\uB2E4\uAC00 \uC790\uAE30\uAC00 \uBB58 \uC6D0\uD588\uB294\uC9C0 \uC78A\uB294 \uC21C\uAC04\uC774 \uC624\uB2C8, \uC6D0\uD558\uB294 \uAC83\uC744 \uBA3C\uC800 \uB9D0\uD574 \uBC84\uB987\uD558\uB294 \uD3B8\uC774 \uC88B\uC2B5\uB2C8\uB2E4."
  },
  \uBCD1: {
    image: "\uD55C\uB0AE\uC758 \uD0DC\uC591",
    text: "\uC228\uAE30\uC9C0 \uBABB\uD558\uB294 \uBC1D\uC74C\uC744 \uAC00\uC9C4 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uC5B4\uB514\uC5D0 \uC788\uB4E0 \uC874\uC7AC\uAC00 \uB4DC\uB7EC\uB098\uACE0 \uBD84\uC704\uAE30\uB97C \uBC14\uAFB8\uBA70, \uC0AC\uB78C\uC744 \uBAA8\uC73C\uB294 \uC77C\uC5D0 \uC7AC\uB2A5\uC774 \uC788\uC2B5\uB2C8\uB2E4. \uB2E4\uB9CC \uAC10\uC815\uC774 \uADF8\uB300\uB85C \uC5BC\uAD74\uC5D0 \uB098\uC624\uACE0 \uC5D0\uB108\uC9C0\uB97C \uD55C\uAEBC\uBC88\uC5D0 \uC4F0\uB294 \uD3B8\uC774\uB77C, \uB728\uAC70\uC6CC\uC9C4 \uB2E4\uC74C\uC5D0 \uC5B4\uB5BB\uAC8C \uC2DD\uD790\uC9C0\uB97C \uBBF8\uB9AC \uC815\uD574\uB450\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4."
  },
  \uC815: {
    image: "\uC5B4\uB460 \uC18D\uC758 \uB4F1\uBD88",
    text: "\uC791\uC9C0\uB9CC \uC624\uB798 \uBC1D\uD788\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uB113\uAC8C \uD37C\uC9C0\uAE30\uBCF4\uB2E4 \uAC00\uAE4C\uC6B4 \uC0AC\uB78C\uC744 \uAE4A\uC774 \uBE44\uCD94\uACE0, \uADF8\uB798\uC11C \uACC1\uC5D0 \uC788\uB294 \uC774\uB4E4\uC774 \uADF8 \uC628\uAE30\uB97C \uC555\uB2C8\uB2E4. \uAC89\uC73C\uB85C \uC870\uC6A9\uD574 \uBCF4\uC5EC\uB3C4 \uC18D\uC5D0\uC11C\uB294 \uACC4\uC18D \uBB34\uC5B8\uAC00 \uD0C0\uACE0 \uC788\uC5B4, \uC3DF\uC744 \uACF3\uC744 \uD558\uB098 \uC815\uD574\uC8FC\uC9C0 \uC54A\uC73C\uBA74 \uC2A4\uC2A4\uB85C\uB97C \uD0DC\uC6C1\uB2C8\uB2E4."
  },
  \uBB34: {
    image: "\uC0B0\uACFC \uB4E4\uCC98\uB7FC \uD06C\uACE0 \uB2E8\uB2E8\uD55C \uD759",
    text: "\uC27D\uAC8C \uD754\uB4E4\uB9AC\uC9C0 \uC54A\uACE0 \uC8FC\uBCC0 \uC0AC\uB78C\uC774 \uAE30\uB300\uC624\uB294 \uC790\uB9AC\uB97C \uC790\uC5F0\uC2A4\uB7FD\uAC8C \uB9E1\uC2B5\uB2C8\uB2E4. \uB9D0\uC774 \uB9CE\uC9C0 \uC54A\uC544\uB3C4 \uC788\uB294 \uAC83\uB9CC\uC73C\uB85C \uC790\uB9AC\uAC00 \uC548\uC815\uB418\uACE0, \uADF8\uB798\uC11C \uCC45\uC784\uC774 \uACC4\uC18D \uBAB0\uB9BD\uB2C8\uB2E4. \uB2E4\uB9CC \uD55C\uBC88 \uC790\uB9AC\uB97C \uC7A1\uC73C\uBA74 \uC798 \uC6C0\uC9C1\uC774\uC9C0 \uC54A\uC544, \uBC29\uD5A5\uC744 \uBC14\uAFD4\uC57C \uD560 \uB54C\uAC00 \uC778\uC0DD\uC5D0\uC11C \uAC00\uC7A5 \uC5B4\uB824\uC6B4 \uC21C\uAC04\uC774 \uB429\uB2C8\uB2E4."
  },
  \uAE30: {
    image: "\uC0AC\uB78C\uC774 \uC77C\uAD6C\uB294 \uB17C\uBC2D",
    text: "\uBB34\uC5C7\uC774\uB4E0 \uBC1B\uC544 \uD0A4\uC6CC\uB0B4\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uB0A8\uC744 \uB3CC\uBCF4\uACE0 \uC790\uB9AC\uB97C \uB9CC\uB4E4\uC5B4 \uC8FC\uB294 \uB370 \uC7AC\uB2A5\uC774 \uC788\uACE0, \uADF8 \uACFC\uC815\uC5D0\uC11C \uC2E4\uC18D\uB3C4 \uAF64 \uC798 \uCC59\uAE41\uB2C8\uB2E4. \uB300\uC2E0 \uD488\uC774 \uB113\uC740 \uB9CC\uD07C \uC544\uBB34\uB098 \uB4E4\uC774\uAE30 \uC26C\uC6CC\uC11C, \uB204\uAD6C\uB97C \uACC1\uC5D0 \uB458\uC9C0 \uACE0\uB974\uB294 \uC77C\uC774 \uACE7 \uC778\uC0DD\uC758 \uBC29\uD5A5\uC744 \uC815\uD569\uB2C8\uB2E4."
  },
  \uACBD: {
    image: "\uC544\uC9C1 \uB2E4\uB4EC\uC9C0 \uC54A\uC740 \uBB34\uC1E0",
    text: "\uB9FA\uACE0 \uB04A\uC74C\uC774 \uBD84\uBA85\uD558\uACE0 \uACB0\uC815\uC744 \uBE68\uB9AC \uB0B4\uB9AC\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uC560\uB9E4\uD55C \uC0C1\uD0DC\uB97C \uC624\uB798 \uBABB \uACAC\uB38C \uACB0\uB860\uBD80\uD130 \uB0B4\uBC84\uB9AC\uB294\uB370, \uADF8 \uC18D\uB3C4\uAC00 \uAE30\uD68C\uB97C \uC7A1\uAE30\uB3C4 \uD558\uACE0 \uAD00\uACC4\uB97C \uB2E4\uCE58\uAC8C\uB3C4 \uD569\uB2C8\uB2E4. \uB2E8\uB828\uB420\uC218\uB85D \uAC15\uD574\uC9C0\uB294 \uC131\uC9C8\uC774\uB77C, \uCD08\uB144\uC758 \uACE0\uC0DD\uC774 \uC544\uAE5D\uC9C0 \uC54A\uC740 \uC720\uD615\uC785\uB2C8\uB2E4."
  },
  \uC2E0: {
    image: "\uC138\uACF5\uC744 \uB9C8\uCE5C \uBCF4\uC11D",
    text: "\uAE30\uC900\uC774 \uB192\uACE0 \uAC10\uAC01\uC774 \uC608\uB9AC\uD55C \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uC5B4\uC124\uD504\uAC8C \uB118\uC5B4\uAC00\uB294 \uAC83\uC744 \uBABB \uACAC\uB514\uACE0, \uADF8 \uAE4C\uB2E4\uB85C\uC6C0\uC774 \uACB0\uACFC\uC758 \uC644\uC131\uB3C4\uB97C \uB9CC\uB4ED\uB2C8\uB2E4. \uB2E4\uB9CC \uAC19\uC740 \uAE30\uC900\uC744 \uB0A8\uC5D0\uAC8C\uB3C4 \uB4E4\uC774\uB300\uBA74 \uD63C\uC790 \uB0A8\uAC8C \uB418\uB2C8, \uC790\uC2E0\uC5D0\uAC8C \uC4F0\uB294 \uC7A3\uB300\uC640 \uB0A8\uC5D0\uAC8C \uC4F0\uB294 \uC7A3\uB300\uB97C \uB098\uB220 \uB450\uB294 \uD3B8\uC774 \uC88B\uC2B5\uB2C8\uB2E4."
  },
  \uC784: {
    image: "\uAE4A\uACE0 \uB113\uC740 \uBC14\uB2E4",
    text: "\uC0DD\uAC01\uC758 \uD3ED\uC774 \uB113\uACE0 \uC2A4\uCF00\uC77C\uC774 \uD070 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uC0AC\uB78C\uC744 \uC798 \uBC1B\uC544\uB4E4\uC774\uACE0 \uD310\uC774 \uCEE4\uC9C8\uC218\uB85D \uD798\uC774 \uB098\uBA70, \uC791\uC740 \uC77C\uC5D0\uB294 \uC880\uCC98\uB7FC \uD765\uC774 \uBD99\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uB2E4 \uBC1B\uC544\uC8FC\uB2E4 \uC2A4\uC2A4\uB85C \uC9C0\uCE58\uB294 \uAD6C\uC870\uB77C, \uC5B4\uB514\uAE4C\uC9C0 \uBC1B\uC744\uC9C0 \uC120\uC744 \uBBF8\uB9AC \uADF8\uC5B4\uB450\uB294 \uAC83\uC774 \uC790\uAE30\uB97C \uC9C0\uD0A4\uB294 \uBC29\uBC95\uC785\uB2C8\uB2E4."
  },
  \uACC4: {
    image: "\uC774\uC2AC\uACFC \uC2E4\uAC1C\uCC9C\uC758 \uBB3C",
    text: "\uC12C\uC138\uD558\uACE0 \uAC10\uC218\uC131\uC774 \uAE4A\uC740 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uB0A8\uC758 \uB9C8\uC74C\uC744 \uC798 \uC77D\uACE0 \uD544\uC694\uD55C \uC790\uB9AC\uC5D0 \uC815\uD655\uD788 \uC2A4\uBA70\uB4E4\uC5B4, \uC0C1\uB2F4\xB7\uAE30\uD68D\xB7\uCC3D\uC791\uCC98\uB7FC \uC0AC\uB78C\uC744 \uB2E4\uB8E8\uB294 \uC77C\uC5D0\uC11C \uD798\uC744 \uB0C5\uB2C8\uB2E4. \uB300\uC2E0 \uB0A8\uC758 \uAC10\uC815\uC744 \uC790\uAE30 \uAC83\uCC98\uB7FC \uBC1B\uC544\uBC84\uB9AC\uB294 \uD3B8\uC774\uB77C, \uAC10\uC815\uACFC \uC790\uC2E0\uC744 \uBD84\uB9AC\uD558\uB294 \uC5F0\uC2B5\uC774 \uD3C9\uC0DD \uD544\uC694\uD569\uB2C8\uB2E4."
  }
};
var ELEMENT_BALANCE = {
  \uBAA9: {
    \uACFC\uB2E4: "\uBED7\uC5B4\uB098\uAC00\uB824\uB294 \uD798\uC774 \uACFC\uD569\uB2C8\uB2E4. \uC2DC\uC791\uD558\uACE0 \uC2F6\uC740 \uC77C\uC774 \uB298 \uC5EC\uB7EC \uAC1C\uACE0 \uACC4\uD68D\uB3C4 \uC798 \uC11C\uC9C0\uB9CC, \uBC8C\uC778 \uAC83\uC744 \uAC70\uB46C\uB4E4\uC774\uB294 \uB370\uC11C \uC790\uC8FC \uB9C9\uD799\uB2C8\uB2E4. \uC0C8\uB85C \uC2DC\uC791\uD558\uAE30 \uC804\uC5D0 \uC774\uBBF8 \uBC8C\uC778 \uAC83\uC744 \uD558\uB098 \uB2EB\uB294 \uC2B5\uAD00\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.",
    \uBC1C\uB2EC: "\uC790\uB77C\uACE0 \uBED7\uC5B4\uB098\uAC00\uB294 \uAE30\uC6B4\uC774 \uC801\uB2F9\uD788 \uC788\uC2B5\uB2C8\uB2E4. \uC0C8\uB85C\uC6B4 \uAC83\uC744 \uBC30\uC6B0\uACE0 \uBC29\uD5A5\uC744 \uC7A1\uB294 \uB370 \uBB34\uB9AC\uAC00 \uC5C6\uACE0, \uC131\uC7A5\uC774 \uD544\uC694\uD55C \uC2DC\uAE30\uC5D0 \uC54C\uC544\uC11C \uC6C0\uC9C1\uC785\uB2C8\uB2E4.",
    \uBD80\uC871: "\uBC00\uACE0 \uB098\uAC00\uB294 \uCD94\uC9C4\uB825\uC774 \uC57D\uD55C \uD3B8\uC785\uB2C8\uB2E4. \uACB0\uC815\uC744 \uBBF8\uB8E8\uAC70\uB098 \uB0A8\uC774 \uC815\uD574\uC8FC\uAE30\uB97C \uAE30\uB2E4\uB9AC\uB294 \uCABD\uC774\uB77C, \uC2DC\uC791 \uC790\uCCB4\uB97C \uB3C4\uC640\uC904 \uC0AC\uB78C\uC774\uB098 \uB9C8\uAC10\uC774 \uC788\uB294 \uD658\uACBD\uC774 \uC798 \uB9DE\uC2B5\uB2C8\uB2E4."
  },
  \uD654: {
    \uACFC\uB2E4: "\uC5F4\uC774 \uB9CE\uC740 \uC0AC\uC8FC\uC785\uB2C8\uB2E4. \uD45C\uD604\uB825\uACFC \uC2DC\uC791\uD558\uB294 \uD798\uC774 \uC88B\uC544 \uC0AC\uB78C\uC744 \uB04C\uC5B4\uB2F9\uAE30\uC9C0\uB9CC, \uC2DD\uD788\uACE0 \uC815\uB9AC\uD558\uB294 \uAE30\uC6B4\uC774 \uBD80\uC871\uD574 \uD55C\uBC88 \uB2EC\uC544\uC624\uB974\uBA74 \uC2A4\uC2A4\uB85C \uBA48\uCD94\uAE30 \uC5B4\uB835\uC2B5\uB2C8\uB2E4. \uC26C\uB294 \uC2DC\uAC04\uC744 \uC77C\uC815\uC5D0 \uBBF8\uB9AC \uB123\uC5B4 \uB450\uC5B4\uC57C \uD569\uB2C8\uB2E4.",
    \uBC1C\uB2EC: "\uB4DC\uB7EC\uB0B4\uACE0 \uD45C\uD604\uD558\uB294 \uAE30\uC6B4\uC774 \uC54C\uB9DE\uC2B5\uB2C8\uB2E4. \uD544\uC694\uD560 \uB54C \uC55E\uC5D0 \uB098\uC11C\uACE0 \uBB3C\uB7EC\uC124 \uB54C \uBB3C\uB7EC\uC124 \uC904 \uC54C\uC544, \uC0AC\uB78C\uB4E4 \uC0AC\uC774\uC5D0\uC11C \uBB34\uB9AC\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
    \uBD80\uC871: "\uB4DC\uB7EC\uB0B4\uB294 \uAC83\uC744 \uC5B4\uB824\uC6CC\uD558\uB294 \uD3B8\uC785\uB2C8\uB2E4. \uC2E4\uB825\uC774 \uC788\uC5B4\uB3C4 \uD45C\uD604\uC774 \uB2A6\uC5B4 \uC800\uD3C9\uAC00\uB418\uAE30 \uC26C\uC6B0\uB2C8, \uACB0\uACFC\uB97C \uB9D0\uB85C \uC815\uB9AC\uD574 \uC54C\uB9AC\uB294 \uC808\uCC28\uB97C \uC77C\uBD80\uB7EC \uB9CC\uB4E4\uC5B4 \uB450\uB294 \uD3B8\uC774 \uC88B\uC2B5\uB2C8\uB2E4."
  },
  \uD1A0: {
    \uACFC\uB2E4: "\uC9C0\uD0A4\uACE0 \uBC84\uD2F0\uB294 \uD798\uC774 \uACFC\uD569\uB2C8\uB2E4. \uC6EC\uB9CC\uD55C \uC77C\uC5D0\uB294 \uD754\uB4E4\uB9AC\uC9C0 \uC54A\uC9C0\uB9CC, \uADF8\uB9CC\uD07C \uBCC0\uD654\uB97C \uB2A6\uAC8C \uBC1B\uC544\uB4E4\uC5EC \uAE30\uD68C\uAC00 \uC9C0\uB098\uAC04 \uB4A4\uC5D0 \uC6C0\uC9C1\uC774\uB294 \uACBD\uC6B0\uAC00 \uC0DD\uAE41\uB2C8\uB2E4. \uC815\uAE30\uC801\uC73C\uB85C \uD310\uC744 \uD754\uB4E4\uC5B4 \uBCFC \uD544\uC694\uAC00 \uC788\uC2B5\uB2C8\uB2E4.",
    \uBC1C\uB2EC: "\uC911\uC2EC\uC744 \uC7A1\uB294 \uAE30\uC6B4\uC774 \uC801\uB2F9\uD569\uB2C8\uB2E4. \uD310\uB2E8\uC774 \uD55C\uCABD\uC73C\uB85C \uD06C\uAC8C \uAE30\uC6B8\uC9C0 \uC54A\uACE0, \uC0AC\uB78C \uC0AC\uC774\uC5D0\uC11C \uC870\uC728\uD558\uB294 \uC5ED\uD560\uC774 \uC798 \uB9DE\uC2B5\uB2C8\uB2E4.",
    \uBD80\uC871: "\uAE30\uC900\uC744 \uC138\uC6B0\uACE0 \uBC84\uD2F0\uB294 \uD798\uC774 \uC57D\uD55C \uD3B8\uC785\uB2C8\uB2E4. \uC0C1\uD669\uACFC \uC0AC\uB78C\uC5D0 \uB530\uB77C \uB9C8\uC74C\uC774 \uC790\uC8FC \uBC14\uB00C\uBBC0\uB85C, \uC2A4\uC2A4\uB85C \uC815\uD55C \uC6D0\uCE59\uC744 \uB208\uC5D0 \uBCF4\uC774\uAC8C \uC801\uC5B4\uB450\uB294 \uAC83\uC774 \uB3C4\uC6C0\uC774 \uB429\uB2C8\uB2E4."
  },
  \uAE08: {
    \uACFC\uB2E4: "\uC790\uB974\uACE0 \uC815\uB9AC\uD558\uB294 \uD798\uC774 \uACFC\uD569\uB2C8\uB2E4. \uD310\uB2E8\uC774 \uBE60\uB974\uACE0 \uC815\uD655\uD558\uC9C0\uB9CC \uACB0\uB860\uC744 \uB108\uBB34 \uC77C\uCC0D \uB0B4\uB824 \uC0AC\uB78C\uC744 \uB2E4\uCE58\uAC8C \uD558\uB294 \uC77C\uC774 \uC0DD\uAE41\uB2C8\uB2E4. \uACB0\uC815\uC744 \uD558\uB8E8 \uBB35\uD788\uB294 \uADDC\uCE59 \uD558\uB098\uBA74 \uD06C\uAC8C \uB2EC\uB77C\uC9D1\uB2C8\uB2E4.",
    \uBC1C\uB2EC: "\uB9FA\uACE0 \uB04A\uB294 \uAE30\uC6B4\uC774 \uC54C\uB9DE\uC2B5\uB2C8\uB2E4. \uD544\uC694\uD55C \uC21C\uAC04\uC5D0 \uACB0\uC815\uC744 \uB0B4\uB9AC\uACE0 \uC544\uB2CC \uAC83\uC744 \uC815\uB9AC\uD560 \uC904 \uC54C\uC544, \uC77C\uC774 \uC624\uB798 \uB298\uC5B4\uC9C0\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
    \uBD80\uC871: "\uC815\uB9AC\uD558\uACE0 \uB05D\uB0B4\uB294 \uD798\uC774 \uC57D\uD55C \uD3B8\uC785\uB2C8\uB2E4. \uAD00\uACC4\uB3C4 \uC77C\uB3C4 \uC815\uB9AC\uD574\uC57C \uD560 \uB54C\uB97C \uB193\uCCD0 \uC624\uB798 \uB04C\uAE30 \uC26C\uC6B0\uB2C8, \uB9C8\uAC10\uACFC \uC815\uB9AC\uB97C \uB300\uC2E0 \uCC59\uACA8\uC904 \uC7A5\uCE58\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4."
  },
  \uC218: {
    \uACFC\uB2E4: "\uC0DD\uAC01\uD558\uACE0 \uD758\uB824\uBCF4\uB0B4\uB294 \uD798\uC774 \uACFC\uD569\uB2C8\uB2E4. \uC544\uC774\uB514\uC5B4\uC640 \uC815\uBCF4\uAC00 \uB04A\uC784\uC5C6\uC774 \uB4E4\uC5B4\uC624\uC9C0\uB9CC \uD55C \uACF3\uC5D0 \uBA38\uBB34\uB974\uC9C0 \uBABB\uD574, \uAE4A\uC774 \uD30C\uAE30 \uC804\uC5D0 \uB2E4\uC74C\uC73C\uB85C \uB118\uC5B4\uAC00\uAE30 \uC27D\uC2B5\uB2C8\uB2E4. \uD55C \uAC00\uC9C0\uB97C \uB05D\uAE4C\uC9C0 \uBD99\uB4DC\uB294 \uD6C8\uB828\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.",
    \uBC1C\uB2EC: "\uC0DD\uAC01\uD558\uACE0 \uC801\uC751\uD558\uB294 \uAE30\uC6B4\uC774 \uC801\uB2F9\uD569\uB2C8\uB2E4. \uC0C1\uD669\uC744 \uC77D\uACE0 \uC720\uC5F0\uD558\uAC8C \uC6C0\uC9C1\uC77C \uC904 \uC54C\uC544 \uB0AF\uC120 \uD658\uACBD\uC5D0\uC11C\uB3C4 \uAE08\uC138 \uC790\uB9AC\uB97C \uC7A1\uC2B5\uB2C8\uB2E4.",
    \uBD80\uC871: "\uBA48\uCDB0\uC11C \uC0DD\uAC01\uD558\uACE0 \uD758\uB824\uBCF4\uB0B4\uB294 \uD798\uC774 \uC57D\uD55C \uD3B8\uC785\uB2C8\uB2E4. \uC313\uC778 \uAC83\uC744 \uD480\uC9C0 \uBABB\uD574 \uC548\uC5D0 \uB2F4\uC544\uB450\uAE30 \uC26C\uC6B0\uB2C8, \uB9D0\uD558\uAC70\uB098 \uC4F0\uB294 \uC2DD\uC73C\uB85C \uBC16\uC73C\uB85C \uB0B4\uBCF4\uB0B4\uB294 \uD1B5\uB85C\uB97C \uD558\uB098 \uB9CC\uB4E4\uC5B4 \uB450\uC138\uC694."
  }
};
var STRENGTH_INTRO = {
  \uC2E0\uAC15: "\uC774\uBBF8 \uC790\uAE30 \uD798\uC774 \uCDA9\uBD84\uD55C \uC0AC\uC8FC\uC785\uB2C8\uB2E4. \uB354 \uBCF4\uD0DC\uAE30\uBCF4\uB2E4 \uB35C\uC5B4\uB0B4\uACE0 \uD758\uB824\uBCF4\uB0B4\uB294 \uCABD\uC774 \uC774\uB86D\uC2B5\uB2C8\uB2E4. \uD63C\uC790 \uB2E4 \uD558\uB824\uB294 \uC790\uB9AC\uBCF4\uB2E4, \uC4F0\uACE0 \uB098\uB204\uACE0 \uB9E1\uAE30\uB294 \uC790\uB9AC\uC5D0\uC11C \uACB0\uACFC\uAC00 \uC798 \uB098\uC635\uB2C8\uB2E4.",
  \uC2E0\uC57D: "\uC790\uAE30 \uD798\uC774 \uB109\uB109\uD558\uC9C0 \uC54A\uC740 \uC0AC\uC8FC\uC785\uB2C8\uB2E4. \uBB34\uB9AC\uD574\uC11C \uBC00\uC5B4\uBD99\uC774\uAE30\uBCF4\uB2E4 \uCC44\uC6B0\uACE0 \uAE30\uB300\uB294 \uCABD\uC774 \uC774\uB86D\uC2B5\uB2C8\uB2E4. \uC88B\uC740 \uC0AC\uB78C\uACFC \uC88B\uC740 \uD658\uACBD\uC744 \uACE0\uB974\uB294 \uC77C\uC774 \uACE7 \uC2E4\uB825\uC774 \uB418\uB294 \uC720\uD615\uC785\uB2C8\uB2E4."
};
var YONGSIN = {
  \uBAA9: {
    need: "\uC790\uB77C\uACE0 \uBED7\uC5B4\uB098\uAC00\uB294 \uBAA9(\u6728)\uC758 \uAE30\uC6B4",
    life: "\uC0C8\uB85C \uBC30\uC6B0\uB294 \uC77C, \uCD08\uB85D\uC774 \uC788\uB294 \uACF5\uAC04, \uC544\uCE68 \uC2DC\uAC04\uB300\uC758 \uD65C\uB3D9\uC774 \uB3C4\uC6C0\uC774 \uB429\uB2C8\uB2E4. \uACC4\uD68D\uC744 \uC138\uC6B0\uACE0 \uBC29\uD5A5\uC744 \uC815\uD558\uB294 \uC77C\uC5D0 \uC2DC\uAC04\uC744 \uC4F0\uBA74 \uD750\uB984\uC774 \uC0B4\uC544\uB0A9\uB2C8\uB2E4.",
    color: "\uCD08\uB85D\xB7\uCCAD\uC0C9",
    direction: "\uB3D9\uCABD",
    season: "\uBD04"
  },
  \uD654: {
    need: "\uBC1D\uD788\uACE0 \uD45C\uD604\uD558\uB294 \uD654(\u706B)\uC758 \uAE30\uC6B4",
    life: "\uC0AC\uB78C \uC55E\uC5D0 \uC11C\uB294 \uC77C, \uBC1D\uC740 \uC870\uBA85\uACFC \uB530\uB73B\uD55C \uACF5\uAC04, \uBAB8\uC744 \uC6C0\uC9C1\uC774\uB294 \uD65C\uB3D9\uC774 \uB3C4\uC6C0\uC774 \uB429\uB2C8\uB2E4. \uC548\uC5D0 \uB2F4\uC544\uB450\uC9C0 \uB9D0\uACE0 \uBC16\uC73C\uB85C \uD45C\uD604\uD558\uB294 \uCABD\uC774 \uC798 \uD480\uB9BD\uB2C8\uB2E4.",
    color: "\uBE68\uAC15\xB7\uC8FC\uD669",
    direction: "\uB0A8\uCABD",
    season: "\uC5EC\uB984"
  },
  \uD1A0: {
    need: "\uC911\uC2EC\uC744 \uC7A1\uACE0 \uBC84\uD2F0\uB294 \uD1A0(\u571F)\uC758 \uAE30\uC6B4",
    life: "\uADDC\uCE59\uC801\uC778 \uC0DD\uD65C, \uD759\uACFC \uB3C4\uC790\uAE30\uCC98\uB7FC \uBB34\uAC8C\uAC00 \uC788\uB294 \uBB3C\uAC74, \uC548\uC815\uB41C \uAD00\uACC4\uAC00 \uB3C4\uC6C0\uC774 \uB429\uB2C8\uB2E4. \uBC8C\uC774\uB294 \uAC83\uBCF4\uB2E4 \uD558\uB098\uB97C \uC624\uB798 \uC9C0\uD0A4\uB294 \uCABD\uC5D0\uC11C \uC131\uACFC\uAC00 \uB0A9\uB2C8\uB2E4.",
    color: "\uBCA0\uC774\uC9C0\xB7\uD669\uD1A0",
    direction: "\uC911\uC559",
    season: "\uD658\uC808\uAE30"
  },
  \uAE08: {
    need: "\uC815\uB9AC\uD558\uACE0 \uB9E4\uB4ED\uC9D3\uB294 \uAE08(\u91D1)\uC758 \uAE30\uC6B4",
    life: "\uBE44\uC6B0\uACE0 \uC815\uB9AC\uD558\uB294 \uC77C, \uAE08\uC18D\uACFC \uD770\uC0C9 \uBB3C\uAC74, \uACB0\uB860\uC744 \uB0B4\uB294 \uC2B5\uAD00\uC774 \uB3C4\uC6C0\uC774 \uB429\uB2C8\uB2E4. \uB298\uC5B4\uB193\uC740 \uAC83\uC744 \uC904\uC77C\uC218\uB85D \uC624\uD788\uB824 \uC77C\uC774 \uC798 \uB3CC\uC544\uAC11\uB2C8\uB2E4.",
    color: "\uD770\uC0C9\xB7\uC740\uC0C9",
    direction: "\uC11C\uCABD",
    season: "\uAC00\uC744"
  },
  \uC218: {
    need: "\uD750\uB974\uACE0 \uCC44\uC6B0\uB294 \uC218(\u6C34)\uC758 \uAE30\uC6B4",
    life: "\uBB3C\uC744 \uC790\uC8FC \uB9C8\uC2DC\uACE0 \uC53B\uC5B4\uB0B4\uB294 \uC77C, \uAC80\uC740\uC0C9\xB7\uC9D9\uC740 \uD30C\uB791 \uC18C\uD488, \uD63C\uC790 \uC0DD\uAC01\uD558\uB294 \uC2DC\uAC04\uC774 \uB3C4\uC6C0\uC774 \uB429\uB2C8\uB2E4. \uC313\uC778 \uAC83\uC744 \uD758\uB824\uBCF4\uB0B4\uB294 \uD1B5\uB85C\uB97C \uB9CC\uB4E4\uC5B4 \uB450\uC138\uC694.",
    color: "\uAC80\uC815\xB7\uC9D9\uC740 \uD30C\uB791",
    direction: "\uBD81\uCABD",
    season: "\uACA8\uC6B8"
  }
};
var TEN_GOD_TRAIT = {
  \uBE44\uACAC: "\uC790\uAE30 \uC8FC\uAD00\uC774 \uB69C\uB837\uD558\uACE0 \uB0A8\uC5D0\uAC8C \uAE30\uB300\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uB3D9\uB4F1\uD55C \uAD00\uACC4\uC5D0\uC11C \uD798\uC774 \uB098\uACE0 \uC704\uC544\uB798\uAC00 \uAC15\uD55C \uC870\uC9C1\uC740 \uB2F5\uB2F5\uD574\uD569\uB2C8\uB2E4. \uD63C\uC790 \uACB0\uC815\uD558\uACE0 \uD63C\uC790 \uCC45\uC784\uC9C0\uB294 \uAD6C\uC870\uAC00 \uC798 \uB9DE\uC9C0\uB9CC, \uADF8\uB7EC\uB2E4 \uACE0\uB9BD\uB418\uC9C0 \uC54A\uAC8C \uC0AC\uB78C\uC744 \uACC1\uC5D0 \uB450\uC138\uC694.",
  \uAC81\uC7AC: "\uACBD\uC7C1\uC774 \uC788\uC744 \uB54C \uC2E4\uB825\uC774 \uC62C\uB77C\uAC11\uB2C8\uB2E4. \uC2B9\uBD80\uB97C \uAC78\uC5B4\uC57C \uD558\uB294 \uC790\uB9AC\uC5D0\uC11C \uAC15\uD558\uACE0, \uC544\uBB34\uB3C4 \uACA8\uB8E8\uC9C0 \uC54A\uC73C\uBA74 \uAE08\uC138 \uD765\uBBF8\uB97C \uC783\uC2B5\uB2C8\uB2E4. \uB2E4\uB9CC \uB3C8\uACFC \uC0AC\uB78C \uBB38\uC81C\uC5D0\uC11C\uB294 \uD55C \uBC1C \uBB3C\uB7EC\uC11C\uB294 \uD3B8\uC774 \uC190\uD574\uAC00 \uC801\uC2B5\uB2C8\uB2E4.",
  \uC2DD\uC2E0: "\uC790\uAE30\uAC00 \uC88B\uC544\uD558\uB294 \uAC83\uC744 \uAFB8\uC900\uD788 \uB9CC\uB4E4\uC5B4 \uB0B4\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uBA39\uACE0 \uC990\uAE30\uACE0 \uD45C\uD604\uD558\uB294 \uB370 \uC7AC\uB2A5\uC774 \uC788\uACE0, \uBAB0\uC544\uCE58\uAE30\uBCF4\uB2E4 \uB9E4\uC77C \uC870\uAE08\uC529 \uD558\uB294 \uBC29\uC2DD\uC774 \uB9DE\uC2B5\uB2C8\uB2E4. \uC5EC\uC720\uAC00 \uC788\uC5B4\uC57C \uACB0\uACFC\uAC00 \uC798 \uB098\uC635\uB2C8\uB2E4.",
  \uC0C1\uAD00: "\uAE30\uC874\uC758 \uBC29\uC2DD\uC5D0 \uADF8\uB300\uB85C \uB530\uB974\uC9C0 \uBABB\uD558\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uB9D0\uACFC \uD45C\uD604\uC5D0 \uC7AC\uB2A5\uC774 \uC788\uACE0 \uD310\uC744 \uBC14\uAFB8\uB294 \uC544\uC774\uB514\uC5B4\uB97C \uB0C5\uB2C8\uB2E4. \uB2E4\uB9CC \uC717\uC0AC\uB78C\uACFC \uBD80\uB52A\uD788\uAE30 \uC26C\uC6B0\uB2C8, \uB300\uC548\uC744 \uD568\uAED8 \uB0B4\uB193\uB294 \uC2B5\uAD00\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.",
  \uD3B8\uC7AC: "\uAE30\uD68C\uB97C \uBCF4\uB294 \uB208\uC774 \uB113\uC2B5\uB2C8\uB2E4. \uC0AC\uB78C\uACFC \uB3C8\uC774 \uB3C4\uB294 \uC790\uB9AC\uC5D0 \uAC10\uAC01\uC774 \uC788\uACE0 \uC218\uC644\uC774 \uC88B\uC9C0\uB9CC, \uD55C \uACF3\uC5D0 \uC624\uB798 \uBB36\uC774\uB294 \uAC78 \uB2F5\uB2F5\uD574\uD569\uB2C8\uB2E4. \uBC8C\uB9AC\uB294 \uB9CC\uD07C \uAD00\uB9AC\uD574 \uC904 \uC0AC\uB78C\uC774 \uACC1\uC5D0 \uC788\uC73C\uBA74 \uC88B\uC2B5\uB2C8\uB2E4.",
  \uC815\uC7AC: "\uC131\uC2E4\uD558\uAC8C \uC313\uC544 \uC62C\uB9AC\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uACC4\uD68D\uD55C \uB9CC\uD07C \uBC8C\uACE0 \uC4F0\uBA70 \uC704\uD5D8\uD55C \uD310\uC5D0\uB294 \uC798 \uB4E4\uC5B4\uAC00\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uC548\uC815\uC801\uC778 \uB300\uC2E0 \uAE30\uD68C\uB97C \uB193\uCE58\uAE30\uB3C4 \uD558\uB2C8, \uACC4\uC0B0\uB41C \uBAA8\uD5D8\uC744 \uAC00\uB054\uC740 \uD5C8\uB77D\uD574 \uC8FC\uC138\uC694.",
  \uD3B8\uAD00: "\uC555\uBC15\uACFC \uCC45\uC784 \uC18D\uC5D0\uC11C \uD798\uC774 \uB098\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uC704\uAE30 \uC0C1\uD669\uC5D0\uC11C \uC624\uD788\uB824 \uCE68\uCC29\uD558\uACE0 \uACB0\uB2E8\uC774 \uBE60\uB974\uBA70, \uB0A8\uB4E4\uC774 \uD53C\uD558\uB294 \uC790\uB9AC\uB97C \uB9E1\uC2B5\uB2C8\uB2E4. \uB2E4\uB9CC \uC790\uC2E0\uC744 \uBAB0\uC544\uBD99\uC774\uB294 \uC2B5\uAD00\uC774 \uBAB8\uC73C\uB85C \uC624\uB2C8 \uC870\uC808\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.",
  \uC815\uAD00: "\uADDC\uCE59\uACFC \uC9C8\uC11C\uB97C \uC911\uC694\uD558\uAC8C \uC5EC\uAE41\uB2C8\uB2E4. \uB9E1\uC740 \uC790\uB9AC\uB97C \uC815\uD655\uD788 \uC9C0\uD0A4\uACE0 \uC2E0\uC6A9\uC744 \uC313\uB294 \uB370 \uAC15\uD574 \uC870\uC9C1\uC5D0\uC11C \uC624\uB798 \uAC11\uB2C8\uB2E4. \uC6D0\uCE59\uC5D0 \uB9E4\uC5EC \uC720\uC5F0\uD568\uC744 \uB193\uCE60 \uB54C\uAC00 \uC788\uC73C\uB2C8 \uC608\uC678\uB97C \uC778\uC815\uD558\uB294 \uC5F0\uC2B5\uC774 \uB3C4\uC6C0\uC774 \uB429\uB2C8\uB2E4.",
  \uD3B8\uC778: "\uB0A8\uACFC \uB2E4\uB978 \uAC01\uB3C4\uB85C \uBCF4\uB294 \uC0AC\uB78C\uC785\uB2C8\uB2E4. \uC815\uD574\uC9C4 \uACF5\uBD80\uBCF4\uB2E4 \uC790\uAE30 \uBC29\uC2DD\uC758 \uD0D0\uAD6C\uC5D0\uC11C \uBE5B\uB098\uACE0, \uC9C1\uAD00\uC774 \uC798 \uB9DE\uC2B5\uB2C8\uB2E4. \uC0DD\uAC01\uC774 \uC548\uC73C\uB85C\uB9CC \uB3CC\uBA74 \uC9C0\uCE58\uB2C8, \uBC16\uC73C\uB85C \uAEBC\uB0B4 \uB193\uB294 \uC790\uB9AC\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4.",
  \uC815\uC778: "\uBC30\uC6B0\uACE0 \uC815\uB9AC\uD558\uB294 \uB370 \uAC15\uD569\uB2C8\uB2E4. \uC0AC\uB78C\uC744 \uB3CC\uBCF4\uACE0 \uAC00\uB974\uCE58\uB294 \uC790\uB9AC\uAC00 \uC798 \uB9DE\uACE0, \uC5B4\uB978\uB4E4\uC758 \uB3C4\uC6C0\uC744 \uBC1B\uB294 \uBCF5\uB3C4 \uC788\uC2B5\uB2C8\uB2E4. \uB2E4\uB9CC \uC900\uBE44\uB9CC \uD558\uB2E4 \uC2DC\uC791\uC774 \uB2A6\uC5B4\uC9C0\uAE30 \uC26C\uC6B0\uB2C8, \uBBF8\uC644\uC131\uC73C\uB85C \uB0B4\uB193\uB294 \uC5F0\uC2B5\uC774 \uD544\uC694\uD569\uB2C8\uB2E4."
};
var YEAR_FLOW = {
  \uBE44\uACAC: "\uB0B4 \uD798\uC744 \uC2A4\uC2A4\uB85C \uC368\uC57C \uD558\uB294 \uD574\uC785\uB2C8\uB2E4. \uB0A8\uC758 \uB3C4\uC6C0\uC744 \uAE30\uB2E4\uB9AC\uAE30\uBCF4\uB2E4 \uC9C1\uC811 \uC6C0\uC9C1\uC77C \uB54C \uACB0\uACFC\uAC00 \uB098\uC624\uACE0, \uB3C5\uB9BD\uC774\uB098 \uC774\uB3D9\uC744 \uC0DD\uAC01\uD558\uAC8C \uB418\uB294 \uC2DC\uAE30\uC774\uAE30\uB3C4 \uD569\uB2C8\uB2E4.",
  \uAC81\uC7AC: "\uACBD\uC7C1\uACFC \uBE44\uAD50\uAC00 \uC7A6\uC544\uC9C0\uB294 \uD574\uC785\uB2C8\uB2E4. \uC790\uADF9\uC774 \uB418\uC5B4 \uC2E4\uB825\uC774 \uC624\uB974\uC9C0\uB9CC, \uB3C8\uC774\uB098 \uC9C0\uBD84\uC774 \uC5BD\uD78C \uC77C\uC5D0\uC11C\uB294 \uACC4\uC57D\uC744 \uD2B9\uD788 \uAF3C\uAF3C\uD788 \uBD10\uC57C \uD558\uB294 \uC2DC\uAE30\uC785\uB2C8\uB2E4.",
  \uC2DD\uC2E0: "\uD45C\uD604\uD558\uACE0 \uB9CC\uB4E4\uC5B4 \uB0B4\uB294 \uD574\uC785\uB2C8\uB2E4. \uD558\uACE0 \uC2F6\uB358 \uAC83\uC744 \uAEBC\uB0B4 \uB193\uAE30\uC5D0 \uC88B\uACE0, \uAC74\uAC15\uACFC \uC5EC\uC720\uB97C \uCC59\uAE30\uBA74\uC11C \uC624\uB798 \uAC08 \uAE30\uBC18\uC744 \uB9CC\uB4E4 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
  \uC0C1\uAD00: "\uD558\uACE0 \uC2F6\uC740 \uB9D0\uC774 \uB9CE\uC544\uC9C0\uB294 \uD574\uC785\uB2C8\uB2E4. \uC0C8 \uC544\uC774\uB514\uC5B4\uC640 \uC0C8 \uBC29\uC2DD\uC774 \uB5A0\uC624\uB974\uC9C0\uB9CC \uAE30\uC874 \uC9C8\uC11C\uC640 \uBD80\uB52A\uD788\uAE30 \uC26C\uC6CC, \uD45C\uD604\uC758 \uC218\uC704\uB97C \uC870\uC808\uD558\uB294 \uAC83\uC774 \uADF8 \uD574\uC758 \uACFC\uC81C\uAC00 \uB429\uB2C8\uB2E4.",
  \uD3B8\uC7AC: "\uC6C0\uC9C1\uC784\uC774 \uB9CE\uC544\uC9C0\uB294 \uD574\uC785\uB2C8\uB2E4. \uC0AC\uB78C\uACFC \uAE30\uD68C\uAC00 \uB113\uAC8C \uB4E4\uC5B4\uC624\uACE0 \uD65C\uB3D9 \uBC18\uACBD\uC774 \uCEE4\uC9C0\uC9C0\uB9CC, \uBC8C\uB9B0 \uB9CC\uD07C \uD758\uB7EC\uB098\uAC00\uAE30\uB3C4 \uC26C\uC6CC \uAD00\uB9AC\uAC00 \uAD00\uAC74\uC785\uB2C8\uB2E4.",
  \uC815\uC7AC: "\uCC28\uACE1\uCC28\uACE1 \uC313\uAE30 \uC88B\uC740 \uD574\uC785\uB2C8\uB2E4. \uD070 \uBCC0\uD654\uBCF4\uB2E4 \uC2E4\uC18D\uC744 \uCC59\uAE30\uB294 \uC2DC\uAE30\uC774\uACE0, \uACC4\uC57D\uC774\uB098 \uC815\uB9AC\uD574\uC57C \uD560 \uB3C8 \uBB38\uC81C\uB97C \uB9C8\uBB34\uB9AC \uC9D3\uAE30\uC5D0 \uC801\uB2F9\uD569\uB2C8\uB2E4.",
  \uD3B8\uAD00: "\uC555\uBC15\uACFC \uCC45\uC784\uC774 \uD568\uAED8 \uB4E4\uC5B4\uC624\uB294 \uD574\uC785\uB2C8\uB2E4. \uBBF8\uB904\uB454 \uC77C\uC774 \uBA3C\uC800 \uB9D0\uC744 \uAC78\uACE0, \uD53C\uD558\uBA74 \uCEE4\uC9C0\uACE0 \uC815\uBA74\uC73C\uB85C \uC7A1\uC73C\uBA74 \uC815\uB9AC\uB429\uB2C8\uB2E4. \uBAB8\uC774 \uBA3C\uC800 \uC2E0\uD638\uB97C \uBCF4\uB0B4\uB2C8 \uBB34\uB9AC\uD558\uC9C0 \uB9C8\uC138\uC694.",
  \uC815\uAD00: "\uC790\uB9AC\uC640 \uC5ED\uD560\uC774 \uBD84\uBA85\uD574\uC9C0\uB294 \uD574\uC785\uB2C8\uB2E4. \uC778\uC815\uBC1B\uAC70\uB098 \uC9C1\uCC45\uC774 \uC815\uD574\uC9C0\uB294 \uD750\uB984\uC774 \uC788\uACE0, \uADDC\uCE59\uACFC \uC808\uCC28\uB97C \uC9C0\uD0AC\uC218\uB85D \uC720\uB9AC\uD558\uAC8C \uD758\uB7EC\uAC11\uB2C8\uB2E4.",
  \uD3B8\uC778: "\uC0DD\uAC01\uC774 \uAE4A\uC5B4\uC9C0\uB294 \uD574\uC785\uB2C8\uB2E4. \uBC30\uC6B0\uACE0 \uC2F6\uC740 \uAC83\uC774 \uC0DD\uAE30\uACE0 \uBC29\uD5A5\uC744 \uB2E4\uC2DC \uBB3B\uAC8C \uB418\uBA70, \uAC89\uC73C\uB85C \uC870\uC6A9\uD574 \uBCF4\uC5EC\uB3C4 \uC548\uC5D0\uC11C \uC815\uB9AC\uAC00 \uC77C\uC5B4\uB0A9\uB2C8\uB2E4.",
  \uC815\uC778: "\uAE30\uB300\uACE0 \uBC30\uC6B0\uAE30 \uC88B\uC740 \uD574\uC785\uB2C8\uB2E4. \uBB38\uC11C\xB7\uC790\uACA9\xB7\uACF5\uBD80\uC640 \uAD00\uB828\uD55C \uC77C\uC774 \uD480\uB9AC\uACE0 \uB3C4\uC640\uC8FC\uB294 \uC0AC\uB78C\uC774 \uB098\uD0C0\uB098\uB294 \uC2DC\uAE30\uC774\uC9C0\uB9CC, \uC900\uBE44\uB9CC \uD558\uB2E4 \uC2DC\uAE30\uB97C \uB193\uCE58\uC9C0 \uC54A\uB3C4\uB85D \uB9C8\uAC10\uC744 \uC815\uD574\uB450\uC138\uC694."
};
var LOCKED_TEASER = [
  "\uC9C0\uAE08 \uC9C0\uB098\uACE0 \uC788\uB294 \uB300\uC6B4\uC740 \uC55E\uC120 \uC2ED \uB144\uACFC \uC131\uACA9\uC774 \uC644\uC804\uD788 \uB2E4\uB985\uB2C8\uB2E4. \uC6D0\uAD6D\uC5D0 \uBE44\uC5B4 \uC788\uB358 \uAE30\uC6B4\uC774 \uB4E4\uC5B4\uC624\uBA74\uC11C \uADF8\uB3D9\uC548 \uBBF8\uB904\uB450\uC5C8\uB358 \uC815\uB9AC\uC640 \uACB0\uC815\uC774 \uD55C\uAEBC\uBC88\uC5D0 \uBAB0\uB9AC\uB294 \uC2DC\uAE30\uC774\uBA70,",
  "\uD2B9\uD788 \uB0B4\uB144\uC5D0\uB294 \uBB38\uC11C\uC640 \uACC4\uC57D\uC5D0 \uAD00\uB828\uD55C \uBCC0\uD654\uAC00 \uB450\uB4DC\uB7EC\uC9D1\uB2C8\uB2E4. \uC9C1\uC5C5 \uC801\uC131\uC73C\uB85C\uB294 \uC0AC\uB78C\uC744 \uC9C1\uC811 \uC0C1\uB300\uD558\uB294 \uC790\uB9AC\uBCF4\uB2E4 \uD310\uC744 \uC124\uACC4\uD558\uB294 \uC790\uB9AC\uAC00 \uB9DE\uACE0,",
  "\uAD00\uACC4\uC5D0\uC11C\uB294 \uAC19\uC740 \uAE30\uC6B4\uC744 \uAC00\uC9C4 \uC0AC\uB78C\uBCF4\uB2E4 \uBE44\uC5B4 \uC788\uB294 \uAE30\uC6B4\uC744 \uCC44\uC6CC\uC8FC\uB294 \uC0AC\uB78C\uACFC \uC624\uB798 \uAC11\uB2C8\uB2E4. \uC6D4\uBCC4\uB85C \uBCF4\uBA74 \uC0C1\uBC18\uAE30\uC640 \uD558\uBC18\uAE30\uC758 \uD750\uB984\uC774 \uB69C\uB837\uD558\uAC8C \uAC08\uB9AC\uB294\uB370\u2026"
].join(" ");

